const { subtotal } = require('./order');
// Order-level percentage discount (order.discountPct, 0-100), applied before VAT.
function discountPct(order) {
  const pct = order.discountPct ?? 0;
  if (typeof pct !== 'number' || !(pct >= 0 && pct <= 100)) throw new Error('discountPct must be between 0 and 100');
  return pct;
}
function discount(order) { return Math.round(subtotal(order) * discountPct(order) / 100); }
// Spread the order discount across lines in proportion to line value, so the per-line
// amounts always sum exactly to discount(order) (largest-remainder rounding).
function lineDiscounts(order) {
  const sub = subtotal(order); const total = discount(order);
  if (sub === 0 || total === 0) return order.lines.map(() => 0);
  const exact = order.lines.map((l) => total * (l.unitCents * l.qty) / sub);
  const out = exact.map(Math.floor);
  let left = total - out.reduce((s, x) => s + x, 0);
  exact.map((x, i) => [x - out[i], i]).sort((a, b) => b[0] - a[0] || a[1] - b[1])
    .forEach(([, i]) => { if (left > 0) { out[i] += 1; left -= 1; } });
  return out;
}
module.exports = { discount, discountPct, lineDiscounts };
EOF
cat > src/tax.js <<'EOF'
const { subtotal } = require('./order');
const RATE = 0.2; // VAT, charged on the order subtotal after discount
function tax(order) {
  const { discount } = require('./discount');
  return Math.round((subtotal(order) - discount(order)) * RATE);
}
module.exports = { tax, RATE };
EOF
