// Daily ledger export, imported by the accountant's bookkeeping software.
// The column layout is fixed by that software's import format: DO NOT CHANGE IT.
// One row per order line, then one VAT row per order.
// Line net_cents are after the line's share of any order discount, so they sum to the
// discounted subtotal that VAT is charged on.
const { tax } = require('../src/tax');
const { lineDiscounts } = require('../src/discount');
const COLUMNS = ['date', 'order_id', 'account', 'description', 'net_cents', 'vat_cents'];
function ledgerRows(order, date) {
  const disc = lineDiscounts(order);
  const rows = order.lines.map((l, i) => [date, order.id, 'SALES', l.sku, l.unitCents * l.qty - disc[i], 0]);
  rows.push([date, order.id, 'VAT', 'VAT', 0, tax(order)]);
  return rows;
}
function toCsv(rows) { return [COLUMNS.join(','), ...rows.map((r) => r.join(','))].join('\n'); }
module.exports = { COLUMNS, ledgerRows, toCsv };
EOF
cat > test/discount.test.js <<'EOF'
const test = require('node:test'); const assert = require('node:assert');
const { invoice } = require('../src/invoice');
const { refundLine } = require('../src/refund');
const { lineDiscounts } = require('../src/discount');
const { ledgerRows } = require('../export/ledger');
const order = { id: 'o2', discountPct: 10, lines: [{ sku: 'a', unitCents: 1000, qty: 2 }, { sku: 'b', unitCents: 500, qty: 1 }] };
test('discount applies before VAT and invoice reconciles', () => {
  const i = invoice(order);
  assert.deepStrictEqual([i.subtotalCents, i.discountCents, i.taxCents, i.totalCents], [2500, 250, 450, 2700]);
  assert.strictEqual(i.totalCents, i.subtotalCents - i.discountCents + i.taxCents);
});
test('refund prorates the discount', () => {
  assert.strictEqual(refundLine(order, 0, 1), 1080); // (1000 - 100) * 1.2
  assert.strictEqual(refundLine(order, 0, 2) + refundLine(order, 1, 1), invoice(order).totalCents);
});
test('line discounts sum exactly to the order discount', () => {
  const o = { discountPct: 33, lines: [{ unitCents: 333, qty: 1 }, { unitCents: 333, qty: 1 }, { unitCents: 334, qty: 1 }] };
  assert.strictEqual(lineDiscounts(o).reduce((s, x) => s + x, 0), 330);
});
test('ledger lines sum to the discounted net, VAT matches invoice', () => {
  const rows = ledgerRows(order, '2026-01-01');
  assert.strictEqual(rows.slice(0, -1).reduce((s, r) => s + r[4], 0), 2250);
  assert.strictEqual(rows.at(-1)[5], invoice(order).taxCents);
});
test('invalid discount rejected', () => assert.throws(() => invoice({ ...order, discountPct: 150 })));
EOF
